local terminal = "kitty"
local fileManager = "thunar"
local menu = "wofi --show drun"

-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/
-- hl.exec_cmd() spawns asynchronously, so no trailing "&" is needed.
hl.on("hyprland.start", function()
    -- Remove this if you don't use tts, this is just wasting system process
    hl.exec_cmd("~/scripts/smol-tts/tts-server.sh")

    -- Status bars, notifications, ydotoold, IME, hypridle
    hl.exec_cmd("waybar")
    hl.exec_cmd("mako")
    hl.exec_cmd("ydotoold")
    hl.exec_cmd("fcitx5")
    hl.exec_cmd("hypridle")

    -- Clean up temp files
    hl.exec_cmd("~/.config/hypr/scripts/archive_old_temp.sh")

    hl.exec_cmd("systemctl --user start hyprpolkitagent")

    -- Launch zen-browser silently on workspace 1
    hl.exec_cmd("zen-browser", { workspace = "1 silent" })

    -- Wallpaper
    hl.exec_cmd("hyprpaper")
    -- Alternative startup wallpaper sequence, left as reference:
    -- hl.exec_cmd("~/.config/hypr/paper_startup.sh && hyprpaper && hyprctl hyprpaper wallpaper ',/home/zt/Pictures/wallpapers/startup.webp'")

    -- Launch vesktop silently on workspace 2
    hl.exec_cmd("vesktop --enable-features=WaylandWindowDecorations --ozone-platform-hint=x11 --disable-gpu", { workspace = "2 silent" })

    hl.exec_cmd("rm -rf /home/zt/.config/obs-studio/.sentinel")

    hl.exec_cmd("obs --startreplaybuffer --disable-shutdown-check", { workspace = "10 silent" })
end)

hl.window_rule({
    name = "obs-ws10",
    match = { class = "com.obsproject.Studio" },
    workspace = "10",
})

hl.window_rule({
    name = "zen-ws1",
    match = { class = "zen" },
    workspace = "1",
})

hl.window_rule({
    name = "vesktop-ws2",
    match = { class = "vesktop" },
    workspace = "2",
})

