-- Better browser navigation experience, remove if unwanted
hl.bind("CTRL + q", hl.dsp.exec_cmd([[hyprctl activewindow -j | jq -e '.class=="zen" or .class=="google-chrome" or .class=="brave-browser"' && ydotool key 104:1 104:0]]))
hl.bind("CTRL + e", hl.dsp.exec_cmd([[hyprctl activewindow -j | jq -e '.class=="zen" or .class=="google-chrome" or .class=="brave-browser"' && ydotool key 109:1 109:0]]))

-- Switch workspaces with mainMod + [0-9], move windows with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

